import json
import os
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = \"https://api.openai.com/v1/responses\"
DEFAULT_MODEL = \"gpt-4.1-mini\"


class OpenAIAPIError(RuntimeError):
    \"\"\"An API request failed without exposing the submitted prompt.\"\"\"


class OpenAIClient:
    \"\"\"Send text prompts to the Responses API without storing responses.\"\"\"

    def __init__(self, api_key=None, model=DEFAULT_MODEL, timeout=60):
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(\"Set OPENAI_API_KEY or pass api_key explicitly\")
        if not isinstance(model, str) or not model.strip():
            raise ValueError(\"model must be a non-empty string\")
        if timeout <= 0:
            raise ValueError(\"timeout must be greater than zero\")
        self.model = model
        self.timeout = timeout

    def create_response(self, prompt, model=None):
        \"\"\"Return the decoded Responses API object for a text prompt.\"\"\"
        if not isinstance(prompt, str):
            raise TypeError(\"prompt must be a string\")

        payload = json.dumps(
            {
                \"model\": model or self.model,
                \"input\": prompt,
                \"store\": False,
            }
        ).encode(\"utf-8\")
        request = Request(
            API_URL,
            data=payload,
            headers={
                \"Authorization\": \"Bearer \" + self.api_key,
                \"Content-Type\": \"application/json\",
            },
            method=\"POST\",
        )

        try:
            with urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode(\"utf-8\"))
        except HTTPError as error:
            raise OpenAIAPIError(
                \"OpenAI API request failed with HTTP status \" + str(error.code)
            ) from None
        except URLError:
            raise OpenAIAPIError(\"Could not connect to the OpenAI API\") from None
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise OpenAIAPIError(\"OpenAI API returned an invalid JSON response\") from None

    def send_prompt(self, prompt, model=None):
        \"\"\"Return concatenated text output for a prompt.\"\"\"
        response = self.create_response(prompt, model=model)
        text_parts = []
        for item in response.get(\"output\", []):
            if item.get(\"type\") "'!= "message":
                continue
            for content in item.get("content", []):
                if content.get("type") == "output_text":
                    text_parts.append(content.get("text", ""))
        return "".join(text_parts)


def send_prompt(prompt, api_key=None, model=DEFAULT_MODEL, timeout=60):
    """Convenience function returning the generated text for one prompt."""
    return OpenAIClient(api_key=[REDACTED_SECRET] model=model, timeout=timeout).send_prompt(
        prompt
    )
